1	package com.example.starter.service;
2	
3	import com.example.starter.domain.AdjustmentTask;
4	import com.example.starter.domain.Assessment;
5	import com.example.starter.domain.HeatingUnit;
6	import com.example.starter.domain.Valve;
7	import com.example.starter.domain.ValveVersion;
8	import com.example.starter.repository.AdjustmentTaskRepository;
9	import com.example.starter.repository.AssessmentRepository;
10	import com.example.starter.repository.StationRepository;
11	import com.example.starter.repository.UnitRepository;
12	import com.example.starter.repository.ValveRepository;
13	import com.example.starter.repository.ValveVersionRepository;
14	import com.fasterxml.jackson.databind.ObjectMapper;
15	import org.springframework.dao.DuplicateKeyException;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.annotation.Transactional;
18	
19	import java.math.BigDecimal;
20	import java.nio.charset.StandardCharsets;
21	import java.security.MessageDigest;
22	import java.security.NoSuchAlgorithmException;
23	import java.time.Clock;
24	import java.time.Duration;
25	import java.time.Instant;
26	import java.util.HexFormat;
27	import java.util.List;
28	
29	/**
30	 * 调节流转核心服务：初调节/再调节指令受理、效果评估、归档终态。
31	 */
32	@Service
33	public class AdjustmentService {
34	
35	    /** 单次步进幅度上限：不超过 10%（恰 10% 合法）。 */
36	    public static final BigDecimal MAX_STEP_PERCENT = new BigDecimal("10");
37	    /** 稳定期：调节后须稳定 4 小时再评估（恰满 4 小时允许评估）。 */
38	    public static final Duration STABILIZATION = Duration.ofHours(4);
39	    /** 24 小时（UTC）窗口内单单元最多调节 3 次（恰 3 次合法），超出转人工复核。 */
40	    public static final int MAX_ADJUSTMENTS_PER_24H = 3;
41	    /** 24 小时窗口长度。 */
42	    public static final Duration ADJUSTMENT_WINDOW = Duration.ofHours(24);
43	
44	    private final StationRepository stationRepository;
45	    private final UnitRepository unitRepository;
46	    private final ValveRepository valveRepository;
47	    private final ValveVersionRepository versionRepository;
48	    private final AdjustmentTaskRepository taskRepository;
49	    private final AssessmentRepository assessmentRepository;
50	    private final BalanceService balanceService;
51	    private final ObjectMapper objectMapper;
52	    private final Clock clock;
53	
54	    public AdjustmentService(StationRepository stationRepository,
55	                             UnitRepository unitRepository,
56	                             ValveRepository valveRepository,
57	                             ValveVersionRepository versionRepository,
58	                             AdjustmentTaskRepository taskRepository,
59	                             AssessmentRepository assessmentRepository,
60	                             BalanceService balanceService,
61	                             ObjectMapper objectMapper,
62	                             Clock clock) {
63	        this.stationRepository = stationRepository;
64	        this.unitRepository = unitRepository;
65	        this.valveRepository = valveRepository;
66	        this.versionRepository = versionRepository;
67	        this.taskRepository = taskRepository;
68	        this.assessmentRepository = assessmentRepository;
69	        this.balanceService = balanceService;
70	        this.objectMapper = objectMapper;
71	        this.clock = clock;
72	    }
73	
74	    /**
75	     * 下达调节令：幂等受理，站内同时刻只允许一个执行中任务；
76	     * 阀门开度写入与版本记录在同一事务内完成。
77	     *
78	     * @param stationId   换热站 ID
79	     * @param requestId   客户端幂等键
80	     * @param unitId      目标单元 ID
81	     * @param stepPercent 步进幅度，单位 %，0 &lt; step &le; 10
82	     * @return 已受理（或幂等重放的首次）任务
83	     */
84	    @Transactional
85	    public AdjustmentTask issueAdjustment(long stationId, String requestId, long unitId,
86	                                          BigDecimal stepPercent) {
87	        String fingerprint = fingerprint("ADJ", requestId, String.valueOf(stationId),
88	                String.valueOf(unitId), stepPercent.stripTrailingZeros().toPlainString());
89	        var existing = taskRepository.findByRequestId(requestId);
90	        if (existing.isPresent()) {
91	            return replayOrConflict(existing.get(), fingerprint);
92	        }
93	        if (stepPercent == null || stepPercent.compareTo(BigDecimal.ZERO) <= 0
94	                || stepPercent.compareTo(MAX_STEP_PERCENT) > 0) {
95	            throw new UnprocessableException("单次步进幅度须为 (0, 10]%，当前: " + stepPercent);
96	        }
97	        // 行级锁串行化同一换热站的任务受理，保证并发下唯一受理。
98	        stationRepository.lockById(stationId)
99	                .orElseThrow(() -> new NotFoundException("换热站不存在: stationId=" + stationId));
100	        // 持锁后重查幂等键：并发下同键请求在前序事务提交后按重放处理。
101	        var existingAfterLock = taskRepository.findByRequestId(requestId);
102	        if (existingAfterLock.isPresent()) {
103	            return replayOrConflict(existingAfterLock.get(), fingerprint);
104	        }
105	        HeatingUnit unit = unitRepository.findById(unitId)
106	                .filter(u -> u.stationId() == stationId)
107	                .orElseThrow(() -> new NotFoundException(
108	                        "单元不存在或不属于该换热站: unitId=" + unitId));
109	        if (taskRepository.existsActiveByStationId(stationId)) {
110	            throw new ConflictException("换热站存在执行中的调节任务，并发下达唯一受理: stationId=" + stationId);
111	        }
112	        Instant now = clock.instant();
113	        int executed = taskRepository.countExecutedSince(unitId, now.minus(ADJUSTMENT_WINDOW));
114	        if (executed >= MAX_ADJUSTMENTS_PER_24H) {
115	            AdjustmentTask review = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
116	                    null, null, null, null, AdjustmentTask.TaskStatus.MANUAL_REVIEW,
117	                    null, null, null, now);
118	            return taskRepository.findById(taskRepository.insert(review)).orElseThrow();
119	        }
120	        BalanceService.BalanceView balance = balanceService.evaluateBalance(stationId, now);
121	        AdjustmentTask.ImbalanceType classification = balance.units().stream()
122	                .filter(u -> u.unitId() == unit.id())
123	                .map(BalanceService.UnitTemperature::classification)
124	                .findFirst()
125	                .orElseThrow(() -> new UnprocessableException(
126	                        "单元无温度数据或未失衡，无法判定调节方向: unitId=" + unitId));
127	        Valve valve = valveRepository.findByUnitId(unitId)
128	                .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
129	        BigDecimal oldOpening = valve.openingPercent();
130	        BigDecimal newOpening = classification == AdjustmentTask.ImbalanceType.UNDERFLOW
131	                ? oldOpening.add(stepPercent) : oldOpening.subtract(stepPercent);
132	        if (newOpening.compareTo(BigDecimal.ZERO) < 0
133	                || newOpening.compareTo(new BigDecimal("100")) > 0) {
134	            throw new UnprocessableException("调节后开度越界 [0,100]%: " + newOpening);
135	        }
136	        AdjustmentTask task = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
137	                classification, stepPercent, oldOpening, newOpening,
138	                AdjustmentTask.TaskStatus.EXECUTING, now, null, null, now);
139	        long taskId;
140	        try {
141	            taskId = taskRepository.insert(task);
142	        } catch (DuplicateKeyException e) {
143	            // 并发下同键插入：唯一约束保证只受理一次，重放首个结果。
144	            return taskRepository.findByRequestId(requestId)
145	                    .map(t -> replayOrConflict(t, fingerprint))
146	                    .orElseThrow(() -> e);
147	        }
148	        // 开度写入与版本记录同事务提交，任一失败整体回滚。
149	        valveRepository.updateOpening(valve.id(), newOpening, now);
150	        versionRepository.insert(valve.id(), taskId,
151	                versionRepository.maxVersionNo(valve.id()) + 1, oldOpening, newOpening, now);
152	        return taskRepository.findById(taskId).orElseThrow();
153	    }
154	
155	    /**
156	     * 效果评估：调节稳定满 4 小时（恰满允许）后执行，幂等键为 requestId。
157	     */
158	    @Transactional
159	    public Assessment assess(long taskId, String requestId) {
160	        String fingerprint = fingerprint("ASM", requestId, String.valueOf(taskId));
161	        var existing = assessmentRepository.findByRequestId(requestId);
162	        if (existing.isPresent()) {
163	            Assessment found = existing.get();
164	            if (!found.fingerprint().equals(fingerprint)) {
165	                throw new ConflictException("同键异参，返回 409: requestId=" + requestId);
166	            }
167	            return found;
168	        }
169	        AdjustmentTask task = taskRepository.findById(taskId)
170	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
171	        switch (task.status()) {
172	            case EXECUTING -> {
173	                // 可评估
174	            }
175	            case ASSESSED -> throw new ConflictException("任务已评估: taskId=" + taskId);
176	            case ARCHIVED -> throw new ConflictException("任务已归档（终态），不允许评估: taskId=" + taskId);
177	            case MANUAL_REVIEW -> throw new ConflictException("任务已转人工复核，不允许评估: taskId=" + taskId);
178	            default -> throw new IllegalStateException("未知任务状态: " + task.status());
179	        }
180	        Instant now = clock.instant();
181	        Instant stabilizedAt = task.executedAt().plus(STABILIZATION);
182	        if (now.isBefore(stabilizedAt)) {
183	            throw new UnprocessableException("稳定期未满 4 小时，可评估时间(UTC): " + stabilizedAt);
184	        }
185	        BalanceService.BalanceView before = balanceService.evaluateBalance(
186	                task.stationId(), task.executedAt());
187	        BalanceService.BalanceView after = balanceService.evaluateBalance(task.stationId(), now);
188	        String detail = toJson(new Comparison(before, after));
189	        Assessment assessment = new Assessment(0, taskId, requestId, fingerprint,
190	                before.diff(), after.diff(), after.balanced(), detail, now);
191	        try {
192	            assessmentRepository.insert(assessment);
193	        } catch (DuplicateKeyException e) {
194	            return assessmentRepository.findByRequestId(requestId)
195	                    .filter(a -> a.fingerprint().equals(fingerprint))
196	                    .orElseThrow(() -> new ConflictException("同键异参，返回 409: requestId=" + requestId));
197	        }
198	        taskRepository.updateStatus(taskId, AdjustmentTask.TaskStatus.ASSESSED, now, null);
199	        return assessmentRepository.findByRequestId(requestId).orElseThrow();
200	    }
201	
202	    /**
203	     * 归档：评估归档为终态，重复归档返回幂等成功。
204	     */
205	    @Transactional
206	    public AdjustmentTask archive(long taskId) {
207	        AdjustmentTask task = taskRepository.findById(taskId)
208	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
209	        switch (task.status()) {
210	            case ARCHIVED -> {
211	                return task;
212	            }
213	            case ASSESSED, MANUAL_REVIEW -> {
214	                taskRepository.updateStatus(taskId, AdjustmentTask.TaskStatus.ARCHIVED,
215	                        null, clock.instant());
216	                return taskRepository.findById(taskId).orElseThrow();
217	            }
218	            case EXECUTING -> throw new ConflictException("任务未评估，不允许归档: taskId=" + taskId);
219	            default -> throw new IllegalStateException("未知任务状态: " + task.status());
220	        }
221	    }
222	
223	    /**
224	     * 查询任务详情。
225	     */
226	    @Transactional(readOnly = true)
227	    public AdjustmentTask getTask(long taskId) {
228	        return taskRepository.findById(taskId)
229	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
230	    }
231	
232	    /**
233	     * 查询任务的评估记录。
234	     */
235	    @Transactional(readOnly = true)
236	    public Assessment getAssessmentByTask(long taskId) {
237	        return assessmentRepository.findByTaskId(taskId)
238	                .orElseThrow(() -> new NotFoundException("任务尚未评估: taskId=" + taskId));
239	    }
240	
241	    /**
242	     * 查询单元阀门完整版本链，可复算开度变迁。
243	     */
244	    @Transactional(readOnly = true)
245	    public List<ValveVersion> getValveVersions(long unitId) {
246	        Valve valve = valveRepository.findByUnitId(unitId)
247	                .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
248	        return versionRepository.findByValveId(valve.id());
249	    }
250	
251	    private AdjustmentTask replayOrConflict(AdjustmentTask existing, String fingerprint) {
252	        if (!existing.fingerprint().equals(fingerprint)) {
253	            throw new ConflictException("同键异参，返回 409 且不改变阀门开度: requestId="
254	                    + existing.requestId());
255	        }
256	        return existing;
257	    }
258	
259	    private String toJson(Object value) {
260	        try {
261	            return objectMapper.writeValueAsString(value);
262	        } catch (Exception e) {
263	            throw new IllegalStateException("评估快照序列化失败", e);
264	        }
265	    }
266	
267	    /**
268	     * 前后温度分布对比，用于评估快照与复算。
269	     */
270	    public record Comparison(BalanceService.BalanceView before, BalanceService.BalanceView after) {
271	    }
272	
273	    static String fingerprint(String... parts) {
274	        try {
275	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
276	            byte[] hash = digest.digest(String.join("|", parts).getBytes(StandardCharsets.UTF_8));
277	            return HexFormat.of().formatHex(hash);
278	        } catch (NoSuchAlgorithmException e) {
279	            throw new IllegalStateException(e);
280	        }
281	    }
282	}
