COMMENT ON COLUMN valve_opening_version.version_no IS '版本号，同一阀门从 1 递增';
COMMENT ON COLUMN valve_opening_version.old_opening IS '变更前开度，单位 %';
COMMENT ON COLUMN valve_opening_version.new_opening IS '变更后开度，单位 %';
