 * 复封后旧铅封保留为历史封号链。
 *
 * @param id           主键
 * @param valveId      受控阀门 ID
 * @param sealNo       铅封号，全局唯一
 * @param valveVersion 封存时阀门开度版本号（从 1 开始）
 * @param status       状态：ACTIVE 当前有效 / RESEALED 已被复封取代
 * @param sealedAt     封存时刻（UTC），由登记请求指定
 * @param requestId    客户端幂等键，全局唯一
 * @param fingerprint  幂等指纹：requestId 与全部业务字段的结构化 SHA-256
 * @param createdAt    台账登记时间（UTC）
 */
public record ValveSeal(long id, long valveId, String sealNo, int valveVersion,
                        SealStatus status, Instant sealedAt, String requestId,
                        String fingerprint, Instant createdAt) {

    /**
     * 铅封状态机：ACTIVE → RESEALED（复封后终结，记录保留）。
     */
    public enum SealStatus {
        /** 当前有效：完整铅封下新的调节令必须拒绝。 */
        ACTIVE,
        /** 已被复封取代：历史封号链保留，不再约束调节。 */
        RESEALED
    }
}

