package com.example.starter.repository;

import com.example.starter.domain.Valve;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.Optional;

/**
 * 阀门数据访问：当前开度的读取与写入。
 */
@Repository
public class ValveRepository {

    private static final RowMapper<Valve> MAPPER = (rs, n) ->
            new Valve(rs.getLong("id"), rs.getLong("unit_id"),
                    rs.getBigDecimal("opening_percent"), rs.getInt("current_version"),
                    rs.getTimestamp("updated_at").toInstant());

    private final JdbcTemplate jdbc;

    public ValveRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按单元 ID 查询阀门。
     */
    public Optional<Valve> findByUnitId(long unitId) {
        return jdbc.query("SELECT id, unit_id, opening_percent, current_version, updated_at"
                + " FROM valve WHERE unit_id = ?", MAPPER, unitId).stream().findFirst();
    }

    /**
     * 按阀门 ID 查询。
     */
    public Optional<Valve> findById(long id) {
        return jdbc.query("SELECT id, unit_id, opening_percent, current_version, updated_at"
                + " FROM valve WHERE id = ?", MAPPER, id).stream().findFirst();
    }

    /**
     * 按单元 ID 查询并加行级写锁（SELECT ... FOR UPDATE），
     * 用于串行化铅封登记、受控调节与复封之间的竞争。
     */
    public Optional<Valve> lockByUnitId(long unitId) {
        return jdbc.query("SELECT id, unit_id, opening_percent, current_version, updated_at"
                + " FROM valve WHERE unit_id = ? FOR UPDATE", MAPPER, unitId).stream().findFirst();
    }

    /**
     * 更新阀门当前开度并递增开度版本号；必须与版本记录在同一事务内调用。
     */
    public void updateOpening(long valveId, BigDecimal newOpening, Instant updatedAt) {
        jdbc.update("UPDATE valve SET opening_percent = ?,"
                        + " current_version = current_version + 1, updated_at = ? WHERE id = ?",
                newOpening, Timestamp.from(updatedAt), valveId);
    }
}

