static String fingerprint(String... parts) {
    StringBuilder sb = new StringBuilder();
    for (String part : parts) {
        if (part == null) {
            sb.append("-1;");
        } else {
            sb.append(part.length()).append(':').append(part).append(';');
        }
    }
    // sha-256 hex
}
