    String fingerprint = fingerprint("SEALED-ADJ", requestId, str(stationId), str(unitId),
            stepPercent == null ? null : stepPercent.stripTrailingZeros().toPlainString(),
            str(expectedVersion), str(unsealOrderId));
    var existing = taskRepository.findByRequestId(requestId);
    if (existing.isPresent()) {
        return replayTaskOrConflict(existing.get(), fingerprint);
    }
    if (stepPercent == null || stepPercent.compareTo(BigDecimal.ZERO) <= 0
            || stepPercent.compareTo(AdjustmentService.MAX_STEP_PERCENT) > 0) {
        throw new UnprocessableException("单次步进幅度须为 (0, 10]%，当前: " + stepPercent);
    }
    UnsealOrder order = orderRepository.findById(unsealOrderId)
            .orElseThrow(() -> new NotFoundException("解封单不存在: orderId=" + unsealOrderId));
    // 站内串行化（同原调节令）
    stationRepository.lockById(stationId)
            .orElseThrow(() -> new NotFoundException("换热站不存在: stationId=" + stationId));
    var afterLock = taskRepository.findByRequestId(requestId);
    if (afterLock.isPresent()) return replayTaskOrConflict(afterLock.get(), fingerprint);
    HeatingUnit unit = unitRepository.findById(unitId)
            .filter(u -> u.stationId() == stationId)
            .orElseThrow(() -> new NotFoundException("单元不存在或不属于该换热站: unitId=" + unitId));
    Valve valve = valveRepository.lockByUnitId(unitId)
            .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
    if (order.valveId() != valve.id()) {
        throw new UnprocessableException("解封单不属于该阀门: orderId=" + unsealOrderId);
    }
    // 事务内重查解封单状态（行锁在 valve 上，复封/撤销串行）
    UnsealOrder current = orderRepository.findById(unsealOrderId).orElseThrow();
    if (current.status() == OrderStatus.REVOKED) {
        throw new UnprocessableException("解封单已撤销，禁止调节: orderId=" + unsealOrderId);
    }
    if (current.status() == OrderStatus.CLOSED) {
        throw new UnprocessableException("解封单已随复封终结，禁止调节: orderId=" + unsealOrderId);
    }
    Instant now = clock.instant();
    if (now.isBefore(current.validFrom()) || !now.isBefore(current.validTo())) {
        throw new UnprocessableException("解封窗口外禁止调节(UTC): 窗口[" + current.validFrom() + ", " + current.validTo() + "), 当前 " + now);
    }
    if (current.quotaUsed() >= current.quotaTotal()) {
        throw new UnprocessableException("解封额度已耗尽: " + current.quotaUsed() + "/" + current.quotaTotal());
    }
    if (valve.currentVersion() != expectedVersion) {
        throw new ConflictException("开度版本不一致: expected=" + expectedVersion + ", current=" + valve.currentVersion());
    }
    if (taskRepository.existsActiveByStationId(stationId)) {
        throw new ConflictException("换热站存在执行中的调节任务: stationId=" + stationId);
    }
    int executed = taskRepository.countExecutedSince(unitId, now.minus(AdjustmentService.ADJUSTMENT_WINDOW));
    if (executed >= AdjustmentService.MAX_ADJUSTMENTS_PER_24H) {
        AdjustmentTask review = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
                null, null, null, null, TaskStatus.MANUAL_REVIEW, unsealOrderId, null, null, null, now);
        return taskRepository.findById(taskRepository.insert(review)).orElseThrow();
    }
    BalanceService.BalanceView balance = balanceService.evaluateBalance(stationId, now);
    ... classification (same as AdjustmentService)
    BigDecimal oldOpening = valve.openingPercent();
    BigDecimal newOpening = ...;
    bounds check;
    AdjustmentTask task = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
            classification, stepPercent, oldOpening, newOpening, TaskStatus.EXECUTING, unsealOrderId, now, null, null, now);
    long taskId;
    try { taskId = taskRepository.insert(task); }
    catch (DuplicateKeyException e) {
        return taskRepository.findByRequestId(requestId).map(t -> replayTaskOrConflict(t, fingerprint)).orElseThrow(() -> e);
    }
    valveRepository.updateOpening(valve.id(), newOpening, now);
    versionRepository.insert(valve.id(), taskId, versionRepository.maxVersionNo(valve.id()) + 1, oldOpening, newOpening, now);
    orderRepository.consumeQuota(unsealOrderId);
    return taskRepository.findById(taskId).orElseThrow();
}
