package com.example.starter.service;

import com.example.starter.domain.AdjustmentTask;
import com.example.starter.domain.HeatingUnit;
import com.example.starter.domain.UnsealOrder;
import com.example.starter.domain.Valve;
import com.example.starter.domain.ValveSeal;
import com.example.starter.repository.AdjustmentTaskRepository;
import com.example.starter.repository.StationRepository;
import com.example.starter.repository.UnitRepository;
import com.example.starter.repository.UnsealOrderRepository;
import com.example.starter.repository.ValveRepository;
import com.example.starter.repository.ValveSealRepository;
import com.example.starter.repository.ValveVersionRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.time.Instant;
import java.util.HexFormat;
import java.util.List;

/**
 * 平衡阀铅封闭环服务：铅封登记、临时解封批准/撤销、受控调节、复封与额度轨迹查询。
 *
 * <p>并发约定：所有写操作先锁阀门行（受控调节先锁换热站行再锁阀门行，与
 * {@link AdjustmentService} 的加锁顺序一致），在事务内重查状态后再原子提交，
 * 业务结果、版本递增与幂等记录同事务落库。
 */
@Service
public class SealService {

    /** 单次解封的调节额度上限：最多两次。 */
    public static final int MAX_QUOTA = 2;

    private final StationRepository stationRepository;
    private final UnitRepository unitRepository;
    private final ValveRepository valveRepository;
    private final ValveSealRepository sealRepository;
    private final UnsealOrderRepository orderRepository;
    private final AdjustmentTaskRepository taskRepository;
    private final ValveVersionRepository versionRepository;
    private final BalanceService balanceService;
    private final Clock clock;

    public SealService(StationRepository stationRepository,
                       UnitRepository unitRepository,
                       ValveRepository valveRepository,
                       ValveSealRepository sealRepository,
                       UnsealOrderRepository orderRepository,
                       AdjustmentTaskRepository taskRepository,
                       ValveVersionRepository versionRepository,
                       BalanceService balanceService,
                       Clock clock) {
        this.stationRepository = stationRepository;
        this.unitRepository = unitRepository;
        this.valveRepository = valveRepository;
        this.sealRepository = sealRepository;
        this.orderRepository = orderRepository;
        this.taskRepository = taskRepository;
        this.versionRepository = versionRepository;
        this.balanceService = balanceService;
        this.clock = clock;
    }

    /**
     * 铅封登记：登记唯一铅封号、当前开度版本与封存时刻；
     * 登记后完整铅封下新的调节令必须拒绝。
     *
     * @param stationId       换热站 ID
     * @param unitId          单元 ID
     * @param requestId       客户端幂等键
     * @param sealNo          铅封号，全局唯一
     * @param expectedVersion 期望的当前开度版本（从 1 开始），不一致返回 409
     * @param sealedAt        封存时刻（UTC）
     * @return 已登记（或幂等重放的首次）铅封台账
     */
    @Transactional
    public ValveSeal registerSeal(long stationId, long unitId, String requestId, String sealNo,
                                  int expectedVersion, Instant sealedAt) {
        String fingerprint = fingerprint("SEAL", requestId, String.valueOf(stationId),
                String.valueOf(unitId), sealNo, String.valueOf(expectedVersion), sealedAt.toString());
        var existing = sealRepository.findByRequestId(requestId);
        if (existing.isPresent()) {
            return replaySealOrConflict(existing.get(), fingerprint);
        }
        // 行级锁串行化同一阀门的登记/复封/受控调节。
        Valve valve = lockValve(stationId, unitId);
        // 持锁后重查幂等键：并发下同键请求在前序事务提交后按重放处理。
        var existingAfterLock = sealRepository.findByRequestId(requestId);
        if (existingAfterLock.isPresent()) {
            return replaySealOrConflict(existingAfterLock.get(), fingerprint);
        }
        requireVersion(valve, expectedVersion);
        if (sealRepository.findActiveByValveId(valve.id()).isPresent()) {
            throw new ConflictException("阀门已存在有效铅封，须复封而非重复登记: unitId=" + unitId);
        }
        ValveSeal seal = new ValveSeal(0, valve.id(), sealNo, expectedVersion,
                ValveSeal.SealStatus.ACTIVE, sealedAt, requestId, fingerprint, clock.instant());
        long id;
        try {
            id = sealRepository.insert(seal);
        } catch (DuplicateKeyException e) {
            // 并发下同键插入按重放处理；铅封号冲突返回 409。
            var byKey = sealRepository.findByRequestId(requestId);
            if (byKey.isPresent()) {
                return replaySealOrConflict(byKey.get(), fingerprint);
            }
            throw new ConflictException("铅封号已存在: sealNo=" + sealNo);
        }
        return sealRepository.findById(id).orElseThrow();
    }

    /**
     * 临时解封批准：引用铅封号及阀门版本，须两名不同授权人共同确认，
     * 固定 UTC 半开窗口 [validFrom, validTo) 与最多两次调节额度；解封生效不改变开度。
     *
     * @param requestId       客户端幂等键
     * @param sealNo          引用的铅封号（须为当前有效铅封）
     * @param expectedVersion 期望的当前开度版本，不一致返回 409
     * @param approver1       第一授权人
     * @param approver2       第二授权人，须与第一授权人不同
     * @param validFrom       窗口起点（UTC，含）
     * @param validTo         窗口终点（UTC，不含；恰到终点失效）
     * @param quota           调节额度，1~2 次
     * @return 已批准（或幂等重放的首次）解封单
     */
    @Transactional
    public UnsealOrder approveUnseal(String requestId, String sealNo, int expectedVersion,
                                     String approver1, String approver2,
                                     Instant validFrom, Instant validTo, int quota) {
        String fingerprint = fingerprint("UNSEAL", requestId, sealNo, String.valueOf(expectedVersion),
                approver1, approver2, validFrom.toString(), validTo.toString(), String.valueOf(quota));
        var existing = orderRepository.findByRequestId(requestId);
        if (existing.isPresent()) {
            return replayOrderOrConflict(existing.get(), fingerprint);
        }
        if (approver1.equals(approver2)) {
            throw new UnprocessableException("临时解封须两名不同授权人共同确认: " + approver1);
        }
        if (!validFrom.isBefore(validTo)) {
            throw new UnprocessableException(
                    "解封窗口起点须早于终点(UTC): " + validFrom + " ~ " + validTo);
        }
        if (quota < 1 || quota > MAX_QUOTA) {
            throw new UnprocessableException("调节额度须为 1~" + MAX_QUOTA + " 次，当前: " + quota);
        }
        ValveSeal seal = sealRepository.findBySealNo(sealNo)
                .orElseThrow(() -> new NotFoundException("铅封号不存在: sealNo=" + sealNo));
        if (seal.status() != ValveSeal.SealStatus.ACTIVE) {
            throw new UnprocessableException("铅封已被复封取代，不可据此解封: sealNo=" + sealNo);
        }
        Valve valve = valveRepository.lockById(seal.valveId())
                .orElseThrow(() -> new NotFoundException("铅封关联阀门不存在: valveId=" + seal.valveId()));
        // 持锁后重查幂等键。
        var existingAfterLock = orderRepository.findByRequestId(requestId);
        if (existingAfterLock.isPresent()) {
            return replayOrderOrConflict(existingAfterLock.get(), fingerprint);
        }
        requireVersion(valve, expectedVersion);
        if (orderRepository.findActiveByValveId(valve.id()).isPresent()) {
            throw new ConflictException("阀门已存在生效中的解封单: valveId=" + valve.id());
        }
        UnsealOrder order = new UnsealOrder(0, valve.id(), seal.id(), sealNo, expectedVersion,
                requestId, fingerprint, approver1, approver2, validFrom, validTo, quota, 0,
                UnsealOrder.OrderStatus.ACTIVE, clock.instant(), null, null, null, null);
        long id;
        try {
            id = orderRepository.insert(order);
        } catch (DuplicateKeyException e) {
            return orderRepository.findByRequestId(requestId)
                    .map(o -> replayOrderOrConflict(o, fingerprint))
                    .orElseThrow(() -> e);
        }
        return orderRepository.findById(id).orElseThrow();
    }

    /**
     * 撤销解封单：撤销后禁止新的受控调节；撤销本身幂等（requestId 为键），失败不占键。
     *
     * @param orderId         解封单 ID
     * @param requestId       撤销操作的客户端幂等键
     * @param expectedVersion 期望的当前开度版本，不一致返回 409
     * @return 撤销后的解封单
     */
    @Transactional
    public UnsealOrder revokeUnseal(long orderId, String requestId, int expectedVersion) {
        String fingerprint = fingerprint("REVOKE", requestId, String.valueOf(orderId),
                String.valueOf(expectedVersion));
        UnsealOrder order = orderRepository.findById(orderId)
                .orElseThrow(() -> new NotFoundException("解封单不存在: orderId=" + orderId));
        if (order.status() == UnsealOrder.OrderStatus.REVOKED) {
            return replayRevokeOrConflict(order, requestId, fingerprint);
        }
        if (order.status() == UnsealOrder.OrderStatus.CLOSED) {
            throw new ConflictException("解封单已随复封终结，不可撤销: orderId=" + orderId);
        }
        Valve valve = valveRepository.lockById(order.valveId())
                .orElseThrow(() -> new NotFoundException("解封单关联阀门不存在: valveId=" + order.valveId()));
        // 持锁后重查状态：与并发撤销/复封串行。
        UnsealOrder locked = orderRepository.findById(orderId).orElseThrow();
        if (locked.status() != UnsealOrder.OrderStatus.ACTIVE) {
            if (locked.status() == UnsealOrder.OrderStatus.REVOKED) {
                return replayRevokeOrConflict(locked, requestId, fingerprint);
            }
            throw new ConflictException("解封单已随复封终结，不可撤销: orderId=" + orderId);
        }
        requireVersion(valve, expectedVersion);
        orderRepository.markRevoked(orderId, requestId, fingerprint, clock.instant());
        return orderRepository.findById(orderId).orElseThrow();
    }

    /**
     * 复封：两名不同人员核对当前开度版本并登记新铅封号；
     * 原子终结旧解封权限且保留历史封号链，不改变开度。
     *
     * @param stationId       换热站 ID
     * @param unitId          单元 ID
     * @param requestId       客户端幂等键
     * @param expectedVersion 期望的当前开度版本，不一致返回 409
     * @param newSealNo       新铅封号，全局唯一
     * @param confirmer1      第一核对人员
     * @param confirmer2      第二核对人员，须与第一人不同
     * @param sealedAt        新铅封封存时刻（UTC）
     * @return 新登记（或幂等重放的首次）铅封台账
     */
    @Transactional
    public ValveSeal reseal(long stationId, long unitId, String requestId, int expectedVersion,
                            String newSealNo, String confirmer1, String confirmer2,
                            Instant sealedAt) {
        String fingerprint = fingerprint("RESEAL", requestId, String.valueOf(stationId),
                String.valueOf(unitId), String.valueOf(expectedVersion), newSealNo,
                confirmer1, confirmer2, sealedAt.toString());
        var existing = sealRepository.findByRequestId(requestId);
        if (existing.isPresent()) {
            return replaySealOrConflict(existing.get(), fingerprint);
        }
        if (confirmer1.equals(confirmer2)) {
            throw new UnprocessableException("复封须两名不同人员核对确认: " + confirmer1);
        }
        Valve valve = lockValve(stationId, unitId);
        var existingAfterLock = sealRepository.findByRequestId(requestId);
        if (existingAfterLock.isPresent()) {
            return replaySealOrConflict(existingAfterLock.get(), fingerprint);
        }
        ValveSeal active = sealRepository.findActiveByValveId(valve.id())
                .orElseThrow(() -> new UnprocessableException(
                        "阀门未处于受控铅封状态，应走铅封登记: unitId=" + unitId));
        requireVersion(valve, expectedVersion);
        Instant now = clock.instant();
        // 原子终结旧解封权限、旧铅封退役、新铅封登记，同一事务提交。
        orderRepository.closeActiveByValveId(valve.id(), now);
        sealRepository.markResealed(active.id());
        ValveSeal newSeal = new ValveSeal(0, valve.id(), newSealNo, expectedVersion,
                ValveSeal.SealStatus.ACTIVE, sealedAt, requestId, fingerprint, now);
        long id;
        try {
            id = sealRepository.insert(newSeal);
        } catch (DuplicateKeyException e) {
            var byKey = sealRepository.findByRequestId(requestId);
            if (byKey.isPresent()) {
                return replaySealOrConflict(byKey.get(), fingerprint);
            }
            throw new ConflictException("铅封号已存在: sealNo=" + newSealNo);
        }
        return sealRepository.findById(id).orElseThrow();
    }

    /**
     * 受控调节：事务内重查解封未撤销、在窗内、额度足够及版本一致，
     * 再原子更新开度、写版本并消费一次额度；失败不消费，重复同键不消费两次。
     * 仍遵守原 10% 步进及 24 小时最多 3 次规则。
     *
     * @param stationId       换热站 ID
     * @param requestId       客户端幂等键
     * @param unitId          目标单元 ID
     * @param stepPercent     步进幅度，单位 %，0 &lt; step &le; 10
     * @param expectedVersion 期望的当前开度版本，不一致返回 409
     * @param unsealOrderId   引用的解封单 ID
     * @return 已受理（或幂等重放的首次）调节任务
     */
    @Transactional
    public AdjustmentTask sealedAdjust(long stationId, String requestId, long unitId,
                                       BigDecimal stepPercent, int expectedVersion,
                                       long unsealOrderId) {
        String fingerprint = fingerprint("SEALED-ADJ", requestId, String.valueOf(stationId),
                String.valueOf(unitId),
                stepPercent == null ? null : stepPercent.stripTrailingZeros().toPlainString(),
                String.valueOf(expectedVersion), String.valueOf(unsealOrderId));
        var existing = taskRepository.findByRequestId(requestId);
        if (existing.isPresent()) {
            return replayTaskOrConflict(existing.get(), fingerprint);
        }
        if (stepPercent == null || stepPercent.compareTo(BigDecimal.ZERO) <= 0
                || stepPercent.compareTo(AdjustmentService.MAX_STEP_PERCENT) > 0) {
            throw new UnprocessableException("单次步进幅度须为 (0, 10]%，当前: " + stepPercent);
        }
        UnsealOrder order = orderRepository.findById(unsealOrderId)
                .orElseThrow(() -> new NotFoundException("解封单不存在: orderId=" + unsealOrderId));
        // 与原调节令一致：先锁换热站行串行化站内受理，再锁阀门行。
        stationRepository.lockById(stationId)
                .orElseThrow(() -> new NotFoundException("换热站不存在: stationId=" + stationId));
        var existingAfterLock = taskRepository.findByRequestId(requestId);
        if (existingAfterLock.isPresent()) {
            return replayTaskOrConflict(existingAfterLock.get(), fingerprint);
        }
        HeatingUnit unit = unitRepository.findById(unitId)
                .filter(u -> u.stationId() == stationId)
                .orElseThrow(() -> new NotFoundException(
                        "单元不存在或不属于该换热站: unitId=" + unitId));
        Valve valve = valveRepository.lockByUnitId(unitId)
                .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
        if (order.valveId() != valve.id()) {
            throw new UnprocessableException(
                    "解封单不属于该单元阀门: orderId=" + unsealOrderId + ", unitId=" + unitId);
        }
        // 持锁后重查解封单：与撤销/复封串行，保证不可已复封仍追加调节版本。
        UnsealOrder current = orderRepository.findById(unsealOrderId).orElseThrow();
        if (current.status() == UnsealOrder.OrderStatus.REVOKED) {
            throw new UnprocessableException("解封单已撤销，禁止调节: orderId=" + unsealOrderId);
        }
        if (current.status() == UnsealOrder.OrderStatus.CLOSED) {
            throw new UnprocessableException("解封单已随复封终结，禁止调节: orderId=" + unsealOrderId);
        }
        Instant now = clock.instant();
        // 半开窗口 [validFrom, validTo)：恰到终点失效。
        if (now.isBefore(current.validFrom()) || !now.isBefore(current.validTo())) {
            throw new UnprocessableException("不在解封窗口内(UTC): 窗口 [" + current.validFrom()
                    + ", " + current.validTo() + ")，当前 " + now);
        }
        if (current.quotaUsed() >= current.quotaTotal()) {
            throw new UnprocessableException("解封额度已耗尽: "
                    + current.quotaUsed() + "/" + current.quotaTotal());
        }
        requireVersion(valve, expectedVersion);
        if (taskRepository.existsActiveByStationId(stationId)) {
            throw new ConflictException(
                    "换热站存在执行中的调节任务，并发下达唯一受理: stationId=" + stationId);
        }
        int executed = taskRepository.countExecutedSince(unitId,
                now.minus(AdjustmentService.ADJUSTMENT_WINDOW));
        if (executed >= AdjustmentService.MAX_ADJUSTMENTS_PER_24H) {
            // 转人工复核：不改动开度、不消费额度。
            AdjustmentTask review = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
                    null, null, null, null, AdjustmentTask.TaskStatus.MANUAL_REVIEW,
                    unsealOrderId, null, null, null, now);
            return taskRepository.findById(taskRepository.insert(review)).orElseThrow();
        }
        BalanceService.BalanceView balance = balanceService.evaluateBalance(stationId, now);
        AdjustmentTask.ImbalanceType classification = balance.units().stream()
                .filter(u -> u.unitId() == unit.id())
                .map(BalanceService.UnitTemperature::classification)
                .findFirst()
                .orElseThrow(() -> new UnprocessableException(
                        "单元无温度数据或未失衡，无法判定调节方向: unitId=" + unitId));
        BigDecimal oldOpening = valve.openingPercent();
        BigDecimal newOpening = classification == AdjustmentTask.ImbalanceType.UNDERFLOW
                ? oldOpening.add(stepPercent) : oldOpening.subtract(stepPercent);
        if (newOpening.compareTo(BigDecimal.ZERO) < 0
                || newOpening.compareTo(new BigDecimal("100")) > 0) {
            throw new UnprocessableException("调节后开度越界 [0,100]%: " + newOpening);
        }
        AdjustmentTask task = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
                classification, stepPercent, oldOpening, newOpening,
                AdjustmentTask.TaskStatus.EXECUTING, unsealOrderId, now, null, null, now);
        long taskId;
        try {
            taskId = taskRepository.insert(task);
        } catch (DuplicateKeyException e) {
            // 并发下同键插入：唯一约束保证只受理一次，重放首个结果，不重复消费额度。
            return taskRepository.findByRequestId(requestId)
                    .map(t -> replayTaskOrConflict(t, fingerprint))
                    .orElseThrow(() -> e);
        }
        // 开度写入、版本记录与额度消费同事务提交，任一失败整体回滚。
        valveRepository.updateOpening(valve.id(), newOpening, now);
        versionRepository.insert(valve.id(), taskId,
                versionRepository.maxVersionNo(valve.id()) + 1, oldOpening, newOpening, now);
        orderRepository.consumeQuota(unsealOrderId);
        return taskRepository.findById(taskId).orElseThrow();
    }

    /**
     * 查询阀门当前有效铅封。
     */
    @Transactional(readOnly = true)
    public ValveSeal currentSeal(long stationId, long unitId) {
        Valve valve = findValve(stationId, unitId);
        return sealRepository.findActiveByValveId(valve.id())
                .orElseThrow(() -> new NotFoundException("阀门无有效铅封: unitId=" + unitId));
    }

    /**
     * 查询阀门完整封号链（含 已被复封取代的历史铅封），按登记顺序。
     */
    @Transactional(readOnly = true)
    public List<ValveSeal> sealHistory(long stationId, long unitId) {
        Valve valve = findValve(stationId, unitId);
        return sealRepository.findByValveId(valve.id());
    }

    /**
     * 查询解封单详情。
     */
    @Transactional(readOnly = true)
    public UnsealOrder getOrder(long orderId) {
        return orderRepository.findById(orderId)
                .orElseThrow(() -> new NotFoundException("解封单不存在: orderId=" + orderId));
    }

    /**
     * 查询解封单额度轨迹：额度总量/已消费量与其产生的受控调节任务。
     */
    @Transactional(readOnly = true)
    public QuotaTrace quotaTrace(long orderId) {
        UnsealOrder order = getOrder(orderId);
        return new QuotaTrace(order, taskRepository.findByUnsealOrderId(orderId));
    }

    /**
     * 额度轨迹：解封单及其名下全部受控调节任务。
     */
    public record QuotaTrace(UnsealOrder order, List<AdjustmentTask> adjustments) {
    }

    private UnsealOrder replayRevokeOrConflict(UnsealOrder revoked, String requestId,
                                               String fingerprint) {
        if (!requestId.equals(revoked.revokeRequestId())) {
            throw new ConflictException("解封单已撤销: orderId=" + revoked.id());
        }
        if (!fingerprint.equals(revoked.revokeFingerprint())) {
            throw new ConflictException("同键异参，返回 409: requestId=" + requestId);
        }
        return revoked;
    }

    private Valve lockValve(long stationId, long unitId) {
        HeatingUnit unit = unitRepository.findById(unitId)
                .filter(u -> u.stationId() == stationId)
                .orElseThrow(() -> new NotFoundException(
                        "单元不存在或不属于该换热站: unitId=" + unitId));
        return valveRepository.lockByUnitId(unit.id())
                .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
    }

    private Valve findValve(long stationId, long unitId) {
        HeatingUnit unit = unitRepository.findById(unitId)
                .filter(u -> u.stationId() == stationId)
                .orElseThrow(() -> new NotFoundException(
                        "单元不存在或不属于该换热站: unitId=" + unitId));
        return valveRepository.findByUnitId(unit.id())
                .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
    }

    private void requireVersion(Valve valve, int expectedVersion) {
        if (valve.currentVersion() != expectedVersion) {
            throw new ConflictException("开度版本不一致: expected=" + expectedVersion
                    + ", current=" + valve.currentVersion());
        }
    }

    private ValveSeal replaySealOrConflict(ValveSeal existing, String fingerprint) {
        if (!existing.fingerprint().equals(fingerprint)) {
            throw new ConflictException("同键异参，返回 409: requestId=" + existing.requestId());
        }
        return existing;
    }

    private UnsealOrder replayOrderOrConflict(UnsealOrder existing, String fingerprint) {
        if (!existing.fingerprint().equals(fingerprint)) {
            throw new ConflictException("同键异参，返回 409: requestId=" + existing.requestId());
        }
        return existing;
    }

    private AdjustmentTask replayTaskOrConflict(AdjustmentTask existing, String fingerprint) {
        if (!existing.fingerprint().equals(fingerprint)) {
            throw new ConflictException("同键异参，返回 409 且不改变阀门开度: requestId="
                    + existing.requestId());
        }
        return existing;
    }

    /**
     * 结构化幂等指纹：各字段以「长度:值;」前缀编码后取 SHA-256，
     * 合法文本含分隔符也可无歧义区分；null 以 -1; 编码。
     */
    static String fingerprint(String... parts) {
        StringBuilder canonical = new StringBuilder();
        for (String part : parts) {
            if (part == null) {
                canonical.append("-1;");
            } else {
                canonical.append(part.length()).append(':').append(part).append(';');
            }
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

