package com.example.starter.web;

import com.example.starter.domain.AdjustmentTask;
import com.example.starter.domain.UnsealOrder;
import com.example.starter.domain.ValveSeal;
import com.example.starter.service.SealService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 平衡阀铅封闭环入口：铅封登记、临时解封批准/撤销、受控调节、复封与额度轨迹查询。
 */
@RestController
@RequestMapping("/api")
public class SealController {

    private final SealService sealService;

    public SealController(SealService sealService) {
        this.sealService = sealService;
    }

    /**
     * 铅封登记请求。
     *
     * @param requestId       客户端幂等键
     * @param sealNo          铅封号，全局唯一
     * @param expectedVersion 期望的当前开度版本（从 1 开始）
     * @param sealedAt        封存时刻（UTC）
     */
    public record SealRegisterRequest(@NotBlank String requestId, @NotBlank String sealNo,
                                      @NotNull Integer expectedVersion,
                                      @NotNull Instant sealedAt) {
    }

    /**
     * 临时解封批准请求。
     *
     * @param requestId       客户端幂等键
     * @param sealNo          引用的铅封号
     * @param expectedVersion 期望的当前开度版本
     * @param approver1       第一授权人
     * @param approver2       第二授权人，须与第一授权人不同
     * @param validFrom       窗口起点（UTC，含）
     * @param validTo         窗口终点（UTC，不含；恰到终点失效）
     * @param quota           调节额度，1~2 次
     */
    public record UnsealApproveRequest(@NotBlank String requestId, @NotBlank String sealNo,
                                       @NotNull Integer expectedVersion,
                                       @NotBlank String approver1, @NotBlank String approver2,
                                       @NotNull Instant validFrom, @NotNull Instant validTo,
                                       @NotNull Integer quota) {
    }

    /**
     * 解封撤销请求。
     *
     * @param requestId       撤销操作的客户端幂等键
     * @param expectedVersion 期望的当前开度版本
     */
    public record UnsealRevokeRequest(@NotBlank String requestId,
                                      @NotNull Integer expectedVersion) {
    }

    /**
     * 复封请求。
     *
     * @param requestId       客户端幂等键
     * @param expectedVersion 期望的当前开度版本
     * @param newSealNo       新铅封号，全局唯一
     * @param confirmer1      第一核对人员
     * @param confirmer2      第二核对人员，须与第一人不同
     * @param sealedAt        新铅封封存时刻（UTC）
     */
    public record ResealRequest(@NotBlank String requestId, @NotNull Integer expectedVersion,
                                @NotBlank String newSealNo,
                                @NotBlank String confirmer1, @NotBlank String confirmer2,
                                @NotNull Instant sealedAt) {
    }

    /**
     * 受控调节请求。
     *
     * @param requestId       客户端幂等键
     * @param unitId          目标单元 ID
     * @param stepPercent     步进幅度，单位 %，(0, 10]，越界由服务层返回 422
     * @param expectedVersion 期望的当前开度版本
     * @param unsealOrderId   引用的解封单 ID
     */
    public record SealedAdjustmentRequest(@NotBlank String requestId, @NotNull Long unitId,
                                          @NotNull BigDecimal stepPercent,
                                          @NotNull Integer expectedVersion,
                                          @NotNull Long unsealOrderId) {
    }

    /**
     * 铅封登记：登记唯一铅封号、当前开度版本与封存时刻。
     */
    @PostMapping("/stations/{stationId}/units/{unitId}/seal")
    public ValveSeal registerSeal(@PathVariable long stationId, @PathVariable long unitId,
                                  @Valid @RequestBody SealRegisterRequest request) {
        return sealService.registerSeal(stationId, unitId, request.requestId(), request.sealNo(),
                request.expectedVersion(), request.sealedAt());
    }

    /**
     * 查询阀门当前有效铅封。
     */
    @GetMapping("/stations/{stationId}/units/{unitId}/seal")
    public ValveSeal currentSeal(@PathVariable long stationId, @PathVariable long unitId) {
        return sealService.currentSeal(stationId, unitId);
    }

    /**
     * 查询阀门完整封号链（含复封历史）。
     */
    @GetMapping("/stations/{stationId}/units/{unitId}/seals")
    public List<ValveSeal> sealHistory(@PathVariable long stationId, @PathVariable long unitId) {
        return sealService.sealHistory(stationId, unitId);
    }

    /**
     * 复封：两名不同人员核对当前开度版本并登记新铅封号，原子终结旧解封权限。
     */
    @PostMapping("/stations/{stationId}/units/{unitId}/reseal")
    public ValveSeal reseal(@PathVariable long stationId, @PathVariable long unitId,
                            @Valid @RequestBody ResealRequest request) {
        return sealService.reseal(stationId, unitId, request.requestId(), request.expectedVersion(),
                request.newSealNo(), request.confirmer1(), request.confirmer2(), request.sealedAt());
    }

    /**
     * 临时解封批准：两名不同授权人共同确认，固定 UTC 半开窗口与最多两次调节额度。
     */
    @PostMapping("/unseal-orders")
    public UnsealOrder approveUnseal(@Valid @RequestBody UnsealApproveRequest request) {
        return sealService.approveUnseal(request.requestId(), request.sealNo(),
                request.expectedVersion(), request.approver1(), request.approver2(),
                request.validFrom(), request.validTo(), request.quota());
    }

    /**
     * 查询解封单详情。
     */
    @GetMapping("/unseal-orders/{orderId}")
    public UnsealOrder getOrder(@PathVariable long orderId) {
        return sealService.getOrder(orderId);
    }

    /**
     * 撤销解封单：撤销后禁止新的受控调节，不自动回拨已改开度。
     */
    @PostMapping("/unseal-orders/{orderId}/revoke")
    public UnsealOrder revokeUnseal(@PathVariable long orderId,
                                    @Valid @RequestBody UnsealRevokeRequest request) {
        return sealService.revokeUnseal(orderId, request.requestId(), request.expectedVersion());
    }

    /**
     * 查询解封单额度轨迹：额度总量/已消费量与其产生的受控调节任务。
     */
    @GetMapping("/unseal-orders/{orderId}/quota-trace")
    public SealService.QuotaTrace quotaTrace(@PathVariable long orderId) {
        return sealService.quotaTrace(orderId);
    }

    /**
     * 受控调节：事务内重查解封未撤销、在窗内、额度足够及版本一致，
     * 原子更新开度、写版本并消费一次额度。
     */
    @PostMapping("/stations/{stationId}/sealed-adjustments")
    public AdjustmentTask sealedAdjust(@PathVariable long stationId,
                                       @Valid @RequestBody SealedAdjustmentRequest request) {
        return sealService.sealedAdjust(stationId, request.requestId(), request.unitId(),
                request.stepPercent(), request.expectedVersion(), request.unsealOrderId());
    }
}

