1	package com.example.starter;
2	
3	import com.example.starter.domain.AdjustmentTask;
4	import com.example.starter.service.AdjustmentService;
5	import com.example.starter.service.ConflictException;
6	import com.example.starter.service.UnprocessableException;
7	import org.junit.jupiter.api.Test;
8	import org.springframework.beans.factory.annotation.Autowired;
9	
10	import java.math.BigDecimal;
11	import java.time.Duration;
12	
13	import static org.assertj.core.api.Assertions.assertThat;
14	import static org.assertj.core.api.Assertions.assertThatThrownBy;
15	
16	/**
17	 * 调节令：步进边界、欠流/过流方向、幂等重放与 24 小时次数上限。
18	 */
19	class AdjustmentServiceTest extends IntegrationTestBase {
20	
21	    @Autowired
22	    private AdjustmentService adjustmentService;
23	
24	    private void imbalancedReadings() {
25	        // U1 欠流（低于均值），U2 过流（高于均值）
26	        submitReadings(40.00, 42.50, 41.00, 41.00);
27	    }
28	
29	    @Test
30	    void 单次恰10个百分点步进合法且欠流开大阀门() {
31	        imbalancedReadings();
32	
33	        AdjustmentTask task = adjustmentService.issueAdjustment(
34	                STATION_ID, "req-step-10", 1L, new BigDecimal("10"));
35	
36	        assertThat(task.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
37	        assertThat(task.classification()).isEqualTo(AdjustmentTask.ImbalanceType.UNDERFLOW);
38	        assertThat(task.oldOpening()).isEqualByComparingTo(new BigDecimal("50.00"));
39	        assertThat(task.newOpening()).isEqualByComparingTo(new BigDecimal("60.00"));
40	        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("60.00"));
41	        // 开度写入与版本记录同事务：版本链第 1 版与当前开度一致
42	        var versions = adjustmentService.getValveVersions(1L);
43	        assertThat(versions).hasSize(1);
44	        assertThat(versions.get(0).newOpening()).isEqualByComparingTo(new BigDecimal("60.00"));
45	    }
46	
47	    @Test
48	    void 单次步进超过10个百分点被拒绝() {
49	        imbalancedReadings();
50	
51	        assertThatThrownBy(() -> adjustmentService.issueAdjustment(
52	                STATION_ID, "req-step-11", 1L, new BigDecimal("10.01")))
53	                .isInstanceOf(UnprocessableException.class);
54	        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("50.00"));
55	        assertThat(countOf("adjustment_task")).isZero();
56	    }
57	
58	    @Test
59	    void 过流单元关小阀门且调节后开度越界被拒绝() {
60	        imbalancedReadings();
61	        jdbc.update("UPDATE valve SET opening_percent = 5.00 WHERE unit_id = 2");
62	
63	        assertThatThrownBy(() -> adjustmentService.issueAdjustment(
64	                STATION_ID, "req-overflow", 2L, new BigDecimal("10")))
65	                .isInstanceOf(UnprocessableException.class);
66	        assertThat(openingOf(2L)).isEqualByComparingTo(new BigDecimal("5.00"));
67	    }
68	
69	    @Test
70	    void 同键同参重放返回首次结果且不重复改开度() {
71	        imbalancedReadings();
72	        AdjustmentTask first = adjustmentService.issueAdjustment(
73	                STATION_ID, "req-idem", 1L, new BigDecimal("5"));
74	
75	        AdjustmentTask replay = adjustmentService.issueAdjustment(
76	                STATION_ID, "req-idem", 1L, new BigDecimal("5"));
77	
78	        assertThat(replay.id()).isEqualTo(first.id());
79	        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
80	        assertThat(countOf("adjustment_task")).isEqualTo(1);
81	        assertThat(countOf("valve_opening_version")).isEqualTo(1);
82	    }
83	
84	    @Test
85	    void 同键异参返回409且不改变阀门开度() {
86	        imbalancedReadings();
87	        adjustmentService.issueAdjustment(STATION_ID, "req-conflict", 1L, new BigDecimal("5"));
88	
89	        assertThatThrownBy(() -> adjustmentService.issueAdjustment(
90	                STATION_ID, "req-conflict", 1L, new BigDecimal("6")))
91	                .isInstanceOf(ConflictException.class);
92	        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
93	        assertThat(countOf("valve_opening_version")).isEqualTo(1);
94	    }
95	
96	    @Test
97	    void 同一单元24小时内恰3次合法第4次转人工复核() {
98	        for (int i = 1; i <= 3; i++) {
99	            imbalancedReadings();
100	            AdjustmentTask task = adjustmentService.issueAdjustment(
101	                    STATION_ID, "req-24h-" + i, 1L, new BigDecimal("5"));
102	            assertThat(task.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
103	            // 稳定满 4 小时后评估并归档，释放站内执行中占位
104	            clock.advance(Duration.ofHours(4));
105	            adjustmentService.assess(task.id(), "req-asm-" + i);
106	            adjustmentService.archive(task.id());
107	        }
108	        assertThat(countOf("adjustment_task")).isEqualTo(3);
109	
110	        imbalancedReadings();
111	        AdjustmentTask fourth = adjustmentService.issueAdjustment(
112	                STATION_ID, "req-24h-4", 1L, new BigDecimal("5"));
113	
114	        assertThat(fourth.status()).isEqualTo(AdjustmentTask.TaskStatus.MANUAL_REVIEW);
115	        assertThat(fourth.executedAt()).isNull();
116	        // 转人工复核不改变阀门开度
117	        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("65.00"));
118	        assertThat(countOf("valve_opening_version")).isEqualTo(3);
119	    }
120	
121	    @Test
122	    void 站内存在执行中任务时新调节令冲突() {
123	        imbalancedReadings();
124	        adjustmentService.issueAdjustment(STATION_ID, "req-active-1", 1L, new BigDecimal("5"));
125	
126	        assertThatThrownBy(() -> adjustmentService.issueAdjustment(
127	                STATION_ID, "req-active-2", 2L, new BigDecimal("5")))
128	                .isInstanceOf(ConflictException.class);
129	        assertThat(countOf("adjustment_task")).isEqualTo(1);
130	    }
131	}
