package com.example.starter;

import com.example.starter.domain.AdjustmentTask;
import com.example.starter.domain.UnsealOrder;
import com.example.starter.domain.ValveSeal;
import com.example.starter.service.AdjustmentService;
import com.example.starter.service.ConflictException;
import com.example.starter.service.NotFoundException;
import com.example.starter.service.SealService;
import com.example.starter.service.UnprocessableException;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import java.math.BigDecimal;
import java.time.Duration;
import java.time.Instant;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * 铅封闭环：登记、临时解封、受控调节、撤销、复封的主流程与失败分支。
 */
class SealServiceTest extends IntegrationTestBase {

    @Autowired
    private SealService sealService;
    @Autowired
    private AdjustmentService adjustmentService;

    private void imbalancedReadings() {
        // U1 欠流（低于均值），U2 过流（高于均值）
        submitReadings(40.00, 42.50, 41.00, 41.00);
    }

    private ValveSeal registerSeal(long unitId, String requestId, String sealNo, int version) {
        return sealService.registerSeal(STATION_ID, unitId, requestId, sealNo, version,
                clock.instant());
    }

    private UnsealOrder approve(String requestId, String sealNo, int version, int quota) {
        return sealService.approveUnseal(requestId, sealNo, version, "授权人甲", "授权人乙",
                clock.instant().minus(Duration.ofHours(1)), clock.instant().plus(Duration.ofHours(72)),
                quota);
    }

    private void assessAndArchive(long taskId) {
        clock.advance(Duration.ofHours(4));
        adjustmentService.assess(taskId, "req-asm-" + taskId);
        adjustmentService.archive(taskId);
    }

    @Test
    void 铅封登记主流程且完整铅封下普通调节令被拒绝() {
        ValveSeal seal = registerSeal(1L, "req-seal-1", "SEAL-001", 1);
        assertThat(seal.status()).isEqualTo(ValveSeal.SealStatus.ACTIVE);
        assertThat(seal.valveVersion()).isEqualTo(1);
        assertThat(seal.sealedAt()).isEqualTo(clock.instant());

        // 完整铅封下新的调节令必须拒绝（422），开度不变
        imbalancedReadings();
        assertThatThrownBy(() -> adjustmentService.issueAdjustment(
                STATION_ID, "req-adj-sealed", 1L, new BigDecimal("5")))
                .isInstanceOf(UnprocessableException.class);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("50.00"));
        assertThat(countOf("adjustment_task")).isZero();

        // 不存在台账的旧阀门仍按原规则工作
        AdjustmentTask task = adjustmentService.issueAdjustment(
                STATION_ID, "req-adj-free", 2L, new BigDecimal("5"));
        assertThat(task.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
        assertThat(openingOf(2L)).isEqualByComparingTo(new BigDecimal("45.00"));
    }

    @Test
    void 铅封登记幂等重放与同键异参409() {
        ValveSeal first = registerSeal(1L, "req-seal-idem", "SEAL-002", 1);

        ValveSeal replay = registerSeal(1L, "req-seal-idem", "SEAL-002", 1);
        assertThat(replay.id()).isEqualTo(first.id());
        assertThat(countOf("valve_seal")).isEqualTo(1);

        assertThatThrownBy(() -> registerSeal(1L, "req-seal-idem", "SEAL-OTHER", 1))
                .isInstanceOf(ConflictException.class);
        assertThat(countOf("valve_seal")).isEqualTo(1);
    }

    @Test
    void 铅封登记失败分支() {
        registerSeal(1L, "req-seal-a", "SEAL-003", 1);

        // 已有有效铅封：重复登记冲突
        assertThatThrownBy(() -> registerSeal(1L, "req-seal-b", "SEAL-004", 1))
                .isInstanceOf(ConflictException.class);
        // 铅封号全局唯一
        assertThatThrownBy(() -> registerSeal(2L, "req-seal-c", "SEAL-003", 1))
                .isInstanceOf(ConflictException.class);
        // 开度版本不一致
        assertThatThrownBy(() -> registerSeal(2L, "req-seal-d", "SEAL-005", 2))
                .isInstanceOf(ConflictException.class);
        // 单元不存在
        assertThatThrownBy(() -> registerSeal(99L, "req-seal-e", "SEAL-006", 1))
                .isInstanceOf(NotFoundException.class);
        // 失败不占键：修正参数后同键可成功
        ValveSeal seal = registerSeal(2L, "req-seal-d", "SEAL-005", 1);
        assertThat(seal.sealNo()).isEqualTo("SEAL-005");
    }

    @Test
    void 解封批准主流程且不改变开度() {
        registerSeal(1L, "req-seal-1", "SEAL-010", 1);

        UnsealOrder order = approve("req-unseal-1", "SEAL-010", 1, 2);

        assertThat(order.status()).isEqualTo(UnsealOrder.OrderStatus.ACTIVE);
        assertThat(order.quotaTotal()).isEqualTo(2);
        assertThat(order.quotaUsed()).isZero();
        assertThat(order.valveVersion()).isEqualTo(1);
        // 解封生效不改变开度
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("50.00"));
        assertThat(countOf("valve_opening_version")).isZero();

        // 同键同参重放
        UnsealOrder replay = approve("req-unseal-1", "SEAL-010", 1, 2);
        assertThat(replay.id()).isEqualTo(order.id());
        assertThat(countOf("unseal_order")).isEqualTo(1);
        // 同键异参 409
        assertThatThrownBy(() -> approve("req-unseal-1", "SEAL-010", 1, 1))
                .isInstanceOf(ConflictException.class);
    }

    @Test
    void 解封批准失败分支() {
        registerSeal(1L, "req-seal-1", "SEAL-011", 1);
        Instant from = clock.instant();
        Instant to = clock.instant().plus(Duration.ofHours(2));

        // 两名授权人相同
        assertThatThrownBy(() -> sealService.approveUnseal("req-u-1", "SEAL-011", 1,
                "授权人甲", "授权人甲", from, to, 2))
                .isInstanceOf(UnprocessableException.class);
        // 窗口起点不早于终点
        assertThatThrownBy(() -> sealService.approveUnseal("req-u-2", "SEAL-011", 1,
                "授权人甲", "授权人乙", to, from, 2))
                .isInstanceOf(UnprocessableException.class);
        // 额度超过两次
        assertThatThrownBy(() -> sealService.approveUnseal("req-u-3", "SEAL-011", 1,
                "授权人甲", "授权人乙", from, to, 3))
                .isInstanceOf(UnprocessableException.class);
        // 铅封号不存在
        assertThatThrownBy(() -> sealService.approveUnseal("req-u-4", "SEAL-UNKNOWN", 1,
                "授权人甲", "授权人乙", from, to, 2))
                .isInstanceOf(NotFoundException.class);
        // 开度版本不一致
        assertThatThrownBy(() -> sealService.approveUnseal("req-u-5", "SEAL-011", 7,
                "授权人甲", "授权人乙", from, to, 2))
                .isInstanceOf(ConflictException.class);
        assertThat(countOf("unseal_order")).isZero();

        // 同阀门同时只允许一个生效中解封单
        approve("req-u-6", "SEAL-011", 1, 2);
        assertThatThrownBy(() -> approve("req-u-7", "SEAL-011", 1, 2))
                .isInstanceOf(ConflictException.class);
        assertThat(countOf("unseal_order")).isEqualTo(1);
    }

    @Test
    void 受控调节窗口内成功并原子消费额度写版本() {
        registerSeal(1L, "req-seal-1", "SEAL-020", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-020", 1, 2);
        imbalancedReadings();

        AdjustmentTask task = sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order.id());

        assertThat(task.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
        assertThat(task.unsealOrderId()).isEqualTo(order.id());
        // 原子结果：开度 50→55、开度版本 1→2、版本链追加、额度消费 1
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
        assertThat(countOf("valve_opening_version")).isEqualTo(1);
        UnsealOrder after = sealService.getOrder(order.id());
        assertThat(after.quotaUsed()).isEqualTo(1);
        // 额度轨迹查询
        SealService.QuotaTrace trace = sealService.quotaTrace(order.id());
        assertThat(trace.adjustments()).hasSize(1);
        assertThat(trace.adjustments().get(0).id()).isEqualTo(task.id());
    }

    @Test
    void 受控调节窗口半开区间恰到终点失效() {
        registerSeal(1L, "req-seal-1", "SEAL-021", 1);
        Instant from = clock.instant().plus(Duration.ofHours(1));
        Instant to = clock.instant().plus(Duration.ofHours(3));
        UnsealOrder order = sealService.approveUnseal("req-unseal-1", "SEAL-021", 1,
                "授权人甲", "授权人乙", from, to, 2);
        imbalancedReadings();

        // 窗口未开始：拒绝且不消费额度
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-early", 1L, new BigDecimal("5"), 1, order.id()))
                .isInstanceOf(UnprocessableException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isZero();

        // 恰到窗口起点（含）：成功
        clock.set(from);
        AdjustmentTask task = sealService.sealedAdjust(
                STATION_ID, "req-sadj-start", 1L, new BigDecimal("5"), 1, order.id());
        assertThat(task.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
        assessAndArchive(task.id());

        // 恰到窗口终点（不含）：失效，拒绝且不消费额度、不回拨开度
        clock.set(to);
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-end", 1L, new BigDecimal("5"), 2, order.id()))
                .isInstanceOf(UnprocessableException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(1);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
    }

    @Test
    void 受控调节额度最多两次且失败不消费() {
        registerSeal(1L, "req-seal-1", "SEAL-022", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-022", 1, 2);
        imbalancedReadings();

        // 版本不符的失败尝试不消费额度
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-badver", 1L, new BigDecimal("5"), 9, order.id()))
                .isInstanceOf(ConflictException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isZero();

        AdjustmentTask first = sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order.id());
        assessAndArchive(first.id());
        imbalancedReadings();
        AdjustmentTask second = sealService.sealedAdjust(
                STATION_ID, "req-sadj-2", 1L, new BigDecimal("5"), 2, order.id());
        assessAndArchive(second.id());
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(2);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("60.00"));

        // 第三次：额度耗尽，拒绝且不消费
        imbalancedReadings();
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-3", 1L, new BigDecimal("5"), 3, order.id()))
                .isInstanceOf(UnprocessableException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(2);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("60.00"));
        assertThat(countOf("valve_opening_version")).isEqualTo(2);
    }

    @Test
    void 受控调节同键重放不重复消费额度() {
        registerSeal(1L, "req-seal-1", "SEAL-023", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-023", 1, 2);
        imbalancedReadings();

        AdjustmentTask first = sealService.sealedAdjust(
                STATION_ID, "req-sadj-idem", 1L, new BigDecimal("5"), 1, order.id());
        AdjustmentTask replay = sealService.sealedAdjust(
                STATION_ID, "req-sadj-idem", 1L, new BigDecimal("5"), 1, order.id());

        assertThat(replay.id()).isEqualTo(first.id());
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(1);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
        assertThat(countOf("valve_opening_version")).isEqualTo(1);

        // 同键异参 409，不消费额度
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-idem", 1L, new BigDecimal("6"), 1, order.id()))
                .isInstanceOf(ConflictException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(1);
    }

    @Test
    void 受控调节仍遵守步进与越界规则() {
        registerSeal(1L, "req-seal-1", "SEAL-024", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-024", 1, 2);
        imbalancedReadings();

        // 步进超过 10%
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-step", 1L, new BigDecimal("10.5"), 1, order.id()))
                .isInstanceOf(UnprocessableException.class);
        // 解封单不属于该单元阀门
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-unit", 2L, new BigDecimal("5"), 1, order.id()))
                .isInstanceOf(UnprocessableException.class);
        // 解封单不存在
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-none", 1L, new BigDecimal("5"), 1, 999L))
                .isInstanceOf(NotFoundException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isZero();
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("50.00"));
    }

    @Test
    void 受控调节24小时上限转人工复核且不消费额度() {
        registerSeal(1L, "req-seal-1", "SEAL-025", 1);
        UnsealOrder order1 = approve("req-unseal-1", "SEAL-025", 1, 2);

        // 第 1、2 次调节（24 小时内）
        imbalancedReadings();
        AdjustmentTask t1 = sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order1.id());
        assessAndArchive(t1.id());
        imbalancedReadings();
        AdjustmentTask t2 = sealService.sealedAdjust(
                STATION_ID, "req-sadj-2", 1L, new BigDecimal("5"), 2, order1.id());
        assessAndArchive(t2.id());

        // 撤销旧单后批准新单（当前版本 3）
        sealService.revokeUnseal(order1.id(), "req-revoke-1", 3);
        UnsealOrder order2 = approve("req-unseal-2", "SEAL-025", 3, 2);

        // 第 3 次调节合法
        imbalancedReadings();
        AdjustmentTask t3 = sealService.sealedAdjust(
                STATION_ID, "req-sadj-3", 1L, new BigDecimal("5"), 3, order2.id());
        assertThat(t3.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
        assessAndArchive(t3.id());

        // 24 小时内第 4 次：转人工复核，不改开度、不消费额度
        imbalancedReadings();
        AdjustmentTask t4 = sealService.sealedAdjust(
                STATION_ID, "req-sadj-4", 1L, new BigDecimal("5"), 4, order2.id());
        assertThat(t4.status()).isEqualTo(AdjustmentTask.TaskStatus.MANUAL_REVIEW);
        assertThat(t4.executedAt()).isNull();
        assertThat(sealService.getOrder(order2.id()).quotaUsed()).isEqualTo(1);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("65.00"));
    }

    @Test
    void 撤销后禁止调节且撤销幂等() {
        registerSeal(1L, "req-seal-1", "SEAL-026", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-026", 1, 2);

        UnsealOrder revoked = sealService.revokeUnseal(order.id(), "req-revoke-1", 1);
        assertThat(revoked.status()).isEqualTo(UnsealOrder.OrderStatus.REVOKED);
        assertThat(revoked.revokedAt()).isEqualTo(clock.instant());

        // 撤销幂等：同键同参重放
        UnsealOrder replay = sealService.revokeUnseal(order.id(), "req-revoke-1", 1);
        assertThat(replay.status()).isEqualTo(UnsealOrder.OrderStatus.REVOKED);
        // 同键异参 409
        assertThatThrownBy(() -> sealService.revokeUnseal(order.id(), "req-revoke-1", 2))
                .isInstanceOf(ConflictException.class);
        // 不同键重复撤销 409
        assertThatThrownBy(() -> sealService.revokeUnseal(order.id(), "req-revoke-2", 1))
                .isInstanceOf(ConflictException.class);

        // 已撤销禁止调节
        imbalancedReadings();
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order.id()))
                .isInstanceOf(UnprocessableException.class);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isZero();
    }

    @Test
    void 撤销版本不符409且撤销不存在解封单404() {
        registerSeal(1L, "req-seal-1", "SEAL-027", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-027", 1, 2);

        assertThatThrownBy(() -> sealService.revokeUnseal(order.id(), "req-revoke-v", 5))
                .isInstanceOf(ConflictException.class);
        assertThat(sealService.getOrder(order.id()).status())
                .isEqualTo(UnsealOrder.OrderStatus.ACTIVE);
        assertThatThrownBy(() -> sealService.revokeUnseal(999L, "req-revoke-none", 1))
                .isInstanceOf(NotFoundException.class);
    }

    @Test
    void 复封主流程原子终结解封且保留封号链() {
        registerSeal(1L, "req-seal-1", "SEAL-030", 1);
        UnsealOrder order = approve("req-unseal-1", "SEAL-030", 1, 2);
        imbalancedReadings();
        AdjustmentTask task = sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order.id());
        assessAndArchive(task.id());

        // 复封：两名不同人员核对当前开度版本（已为 2），登记新铅封号
        ValveSeal newSeal = sealService.reseal(STATION_ID, 1L, "req-reseal-1", 2,
                "SEAL-031", "核对人甲", "核对人乙", clock.instant());

        assertThat(newSeal.status()).isEqualTo(ValveSeal.SealStatus.ACTIVE);
        assertThat(newSeal.valveVersion()).isEqualTo(2);
        // 旧解封权限原子终结
        assertThat(sealService.getOrder(order.id()).status())
                .isEqualTo(UnsealOrder.OrderStatus.CLOSED);
        // 历史封号链保留：旧 RESEALED + 新 ACTIVE
        List<ValveSeal> history = sealService.sealHistory(STATION_ID, 1L);
        assertThat(history).hasSize(2);
        assertThat(history.get(0).sealNo()).isEqualTo("SEAL-030");
        assertThat(history.get(0).status()).isEqualTo(ValveSeal.SealStatus.RESEALED);
        assertThat(history.get(1).sealNo()).isEqualTo("SEAL-031");
        // 复封不改变开度与版本
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
        assertThat(countOf("valve_opening_version")).isEqualTo(1);

        // 复封后旧解封单调节被拒绝
        imbalancedReadings();
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-2", 1L, new BigDecimal("5"), 2, order.id()))
                .isInstanceOf(UnprocessableException.class);
        // 复封后完整铅封下普通调节令仍被拒绝
        assertThatThrownBy(() -> adjustmentService.issueAdjustment(
                STATION_ID, "req-adj-after", 1L, new BigDecimal("5")))
                .isInstanceOf(UnprocessableException.class);

        // 复封幂等重放
        ValveSeal replay = sealService.reseal(STATION_ID, 1L, "req-reseal-1", 2,
                "SEAL-031", "核对人甲", "核对人乙", newSeal.sealedAt());
        assertThat(replay.id()).isEqualTo(newSeal.id());
        assertThat(countOf("valve_seal")).isEqualTo(2);
    }

    @Test
    void 复封失败分支() {
        registerSeal(1L, "req-seal-1", "SEAL-032", 1);

        // 两名确认人相同
        assertThatThrownBy(() -> sealService.reseal(STATION_ID, 1L, "req-rs-1", 1,
                "SEAL-033", "核对人甲", "核对人甲", clock.instant()))
                .isInstanceOf(UnprocessableException.class);
        // 开度版本不一致
        assertThatThrownBy(() -> sealService.reseal(STATION_ID, 1L, "req-rs-2", 9,
                "SEAL-033", "核对人甲", "核对人乙", clock.instant()))
                .isInstanceOf(ConflictException.class);
        // 新铅封号与历史封号冲突
        assertThatThrownBy(() -> sealService.reseal(STATION_ID, 1L, "req-rs-3", 1,
                "SEAL-032", "核对人甲", "核对人乙", clock.instant()))
                .isInstanceOf(ConflictException.class);
        // 未受控阀门复封
        assertThatThrownBy(() -> sealService.reseal(STATION_ID, 2L, "req-rs-4", 1,
                "SEAL-034", "核对人甲", "核对人乙", clock.instant()))
                .isInstanceOf(UnprocessableException.class);
        assertThat(countOf("valve_seal")).isEqualTo(1);
    }

    @Test
    void 解封超时仅禁止新调节不回拨已改开度() {
        registerSeal(1L, "req-seal-1", "SEAL-040", 1);
        UnsealOrder order = sealService.approveUnseal("req-unseal-1", "SEAL-040", 1,
                "授权人甲", "授权人乙", clock.instant().minus(Duration.ofHours(1)),
                clock.instant().plus(Duration.ofHours(2)), 2);
        imbalancedReadings();
        AdjustmentTask task = sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order.id());
        assessAndArchive(task.id());

        // 窗口已过：禁止新调节，但已改开度保持不回拨
        assertThatThrownBy(() -> sealService.sealedAdjust(
                STATION_ID, "req-sadj-2", 1L, new BigDecimal("5"), 2, order.id()))
                .isInstanceOf(UnprocessableException.class);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(1);
    }

    @Test
    void 复封后新铅封可再次解封调节() {
        registerSeal(1L, "req-seal-1", "SEAL-041", 1);
        approve("req-unseal-1", "SEAL-041", 1, 2);
        sealService.reseal(STATION_ID, 1L, "req-reseal-1", 1,
                "SEAL-042", "核对人甲", "核对人乙", clock.instant());

        // 旧铅封已退役，不可据此解封
        assertThatThrownBy(() -> approve("req-unseal-old", "SEAL-041", 1, 2))
                .isInstanceOf(UnprocessableException.class);

        // 新铅封可批准新解封单并受控调节
        UnsealOrder order2 = approve("req-unseal-2", "SEAL-042", 1, 2);
        imbalancedReadings();
        AdjustmentTask task = sealService.sealedAdjust(
                STATION_ID, "req-sadj-1", 1L, new BigDecimal("5"), 1, order2.id());
        assertThat(task.status()).isEqualTo(AdjustmentTask.TaskStatus.EXECUTING);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
    }

    @Test
    void 查询当前铅封与封号链() {
        assertThatThrownBy(() -> sealService.currentSeal(STATION_ID, 1L))
                .isInstanceOf(NotFoundException.class);

        registerSeal(1L, "req-seal-1", "SEAL-050", 1);
        assertThat(sealService.currentSeal(STATION_ID, 1L).sealNo()).isEqualTo("SEAL-050");
        sealService.reseal(STATION_ID, 1L, "req-reseal-1", 1,
                "SEAL-051", "核对人甲", "核对人乙", clock.instant());

        assertThat(sealService.currentSeal(STATION_ID, 1L).sealNo()).isEqualTo("SEAL-051");
        assertThat(sealService.sealHistory(STATION_ID, 1L))
                .extracting(ValveSeal::sealNo)
                .containsExactly("SEAL-050", "SEAL-051");
    }
}

