package com.example.starter;

import com.example.starter.domain.AdjustmentTask;
import com.example.starter.domain.UnsealOrder;
import com.example.starter.domain.ValveSeal;
import com.example.starter.service.ConflictException;
import com.example.starter.service.SealService;
import com.example.starter.service.UnprocessableException;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import java.math.BigDecimal;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.function.IntFunction;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 铅封闭环并发边界：同键重放唯一消费、版本乐观锁串行化、复封与调节竞争唯一。
 */
class SealConcurrencyTest extends IntegrationTestBase {

    @Autowired
    private SealService sealService;

    private record Outcome(Object result, Throwable error) {
    }

    private List<Outcome> runConcurrently(int threads, IntFunction<Object> action)
            throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch gate = new CountDownLatch(1);
        List<Future<Outcome>> futures = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            final int index = i;
            futures.add(pool.submit(() -> {
                gate.await(5, TimeUnit.SECONDS);
                try {
                    return new Outcome(action.apply(index), null);
                } catch (Throwable e) {
                    return new Outcome(null, e);
                }
            }));
        }
        gate.countDown();
        List<Outcome> outcomes = new ArrayList<>();
        for (Future<Outcome> future : futures) {
            try {
                outcomes.add(future.get(30, TimeUnit.SECONDS));
            } catch (Exception e) {
                throw new IllegalStateException("并发用例执行超时或失败", e);
            }
        }
        pool.shutdownNow();
        return outcomes;
    }

    private UnsealOrder prepareOrder(String sealNo, int quota) {
        sealService.registerSeal(STATION_ID, 1L, "req-seal-" + sealNo, sealNo, 1, clock.instant());
        UnsealOrder order = sealService.approveUnseal("req-unseal-" + sealNo, sealNo, 1,
                "授权人甲", "授权人乙", clock.instant().minus(Duration.ofHours(1)),
                clock.instant().plus(Duration.ofHours(72)), quota);
        submitReadings(40.00, 42.50, 41.00, 41.00);
        return order;
    }

    @Test
    void 并发同键受控调节只消费一次额度() throws Exception {
        UnsealOrder order = prepareOrder("SEAL-C1", 2);

        List<Outcome> outcomes = runConcurrently(4,
                i -> sealService.sealedAdjust(STATION_ID, "req-sadj-same", 1L,
                        new BigDecimal("5"), 1, order.id()));

        assertThat(outcomes).allMatch(o -> o.error() == null);
        long distinctTaskIds = outcomes.stream()
                .map(o -> ((AdjustmentTask) o.result()).id()).distinct().count();
        assertThat(distinctTaskIds).isEqualTo(1);
        // 重复同键不消费两次：额度只消费一次，开度只变更一次
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(1);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
        assertThat(countOf("adjustment_task")).isEqualTo(1);
        assertThat(countOf("valve_opening_version")).isEqualTo(1);
    }

    @Test
    void 并发异键受控调节版本乐观锁唯一成功() throws Exception {
        UnsealOrder order = prepareOrder("SEAL-C2", 2);

        List<Outcome> outcomes = runConcurrently(4,
                i -> sealService.sealedAdjust(STATION_ID, "req-sadj-" + i, 1L,
                        new BigDecimal("5"), 1, order.id()));

        long succeeded = outcomes.stream().filter(o -> o.result() != null).count();
        long versionConflict = outcomes.stream()
                .filter(o -> o.error() instanceof ConflictException).count();
        assertThat(succeeded).isEqualTo(1);
        assertThat(versionConflict).isEqualTo(3);
        assertThat(sealService.getOrder(order.id()).quotaUsed()).isEqualTo(1);
        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
        assertThat(countOf("valve_opening_version")).isEqualTo(1);
    }

    @Test
    void 复封与受控调节竞争结果唯一() throws Exception {
        UnsealOrder order = prepareOrder("SEAL-C3", 2);

        List<Outcome> outcomes = runConcurrently(2, i -> {
            if (i == 0) {
                return sealService.sealedAdjust(STATION_ID, "req-race-adj", 1L,
                        new BigDecimal("5"), 1, order.id());
            }
            return sealService.reseal(STATION_ID, 1L, "req-race-reseal", 1,
                    "SEAL-C3-NEW", "核对人甲", "核对人乙", clock.instant());
        });

        Outcome adjust = outcomes.get(0);
        Outcome reseal = outcomes.get(1);
        // 两种合法结局必居其一，且绝不允许「已复封仍追加调节版本」
        if (adjust.result() != null) {
            // 调节先行：复封因版本已推进而冲突，解封单仍生效
            assertThat(adjust.error()).isNull();
            assertThat(reseal.error()).isInstanceOf(ConflictException.class);
            assertThat(countOf("valve_opening_version")).isEqualTo(1);
            assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
            assertThat(sealService.getOrder(order.id()).status())
                    .isEqualTo(UnsealOrder.OrderStatus.ACTIVE);
        } else {
            // 复封先行：调节因解封单已终结而拒绝，不得追加版本
            assertThat(adjust.error()).isInstanceOf(UnprocessableException.class);
            assertThat(reseal.error()).isNull();
            assertThat(((ValveSeal) reseal.result()).sealNo()).isEqualTo("SEAL-C3-NEW");
            assertThat(countOf("valve_opening_version")).isZero();
            assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("50.00"));
            assertThat(sealService.getOrder(order.id()).status())
                    .isEqualTo(UnsealOrder.OrderStatus.CLOSED);
        }
    }

    @Test
    void 并发铅封登记同一阀门唯一受理() throws Exception {
        List<Outcome> outcomes = runConcurrently(2,
                i -> sealService.registerSeal(STATION_ID, 1L, "req-seal-race-" + i,
                        "SEAL-RACE-" + i, 1, clock.instant()));

        long succeeded = outcomes.stream().filter(o -> o.result() != null).count();
        long conflicted = outcomes.stream()
                .filter(o -> o.error() instanceof ConflictException).count();
        assertThat(succeeded).isEqualTo(1);
        assertThat(conflicted).isEqualTo(1);
        assertThat(countOf("valve_seal")).isEqualTo(1);
    }
}

