package com.example.starter.service;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 结构化幂等指纹：合法文本含分隔符也须无歧义区分。
 */
class SealServiceFingerprintTest {

    @Test
    void 含分隔符文本的字段组合不产生歧义() {
        // 朴素分隔符拼接下 ("A", "B|C") 与 ("A|B", "C") 均为 "A|B|C"，结构化编码须区分
        assertThat(SealService.fingerprint("SEAL", "A", "B|C"))
                .isNotEqualTo(SealService.fingerprint("SEAL", "A|B", "C"));
