package com.example.starter;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.Duration;
import java.time.Instant;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 铅封闭环 HTTP 主流程与错误语义：400 参数非法 / 404 不存在 / 409 冲突 / 422 业务拒绝。
 */
@AutoConfigureMockMvc
class SealApiTest extends IntegrationTestBase {

    @Autowired
    private MockMvc mockMvc;

    private String readingsBody() {
        Instant at = clock.instant();
        return """
                {"readings":[
                  {"unitId":1,"temperature":40.00,"recordedAt":"%s"},
                  {"unitId":2,"temperature":42.50,"recordedAt":"%s"},
                  {"unitId":3,"temperature":41.00,"recordedAt":"%s"},
                  {"unitId":4,"temperature":41.00,"recordedAt":"%s"}
                ]}
                """.formatted(at, at, at, at);
    }

    @Test
    void 铅封解封受控调节复封全流程() throws Exception {
        Instant sealedAt = clock.instant();
        // 1. 铅封登记：版本从 1 开始
        mockMvc.perform(post("/api/stations/1/units/1/seal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"req-api-seal","sealNo":"SEAL-API-1",
                                 "expectedVersion":1,"sealedAt":"%s"}
                                """.formatted(sealedAt)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("ACTIVE"))
                .andExpect(jsonPath("$.valveVersion").value(1));

        // 2. 完整铅封下普通调节令被拒绝（422）
        mockMvc.perform(post("/api/stations/1/readings")
                        .contentType(MediaType.APPLICATION_JSON).content(readingsBody()))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/stations/1/adjustments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-api-adj\",\"unitId\":1,\"stepPercent\":5}"))
                .andExpect(status().isUnprocessableEntity());

        // 3. 临时解封批准：两名不同授权人，固定 UTC 窗口，额度 2 次
        Instant from = clock.instant().minus(Duration.ofHours(1));
        Instant to = clock.instant().plus(Duration.ofHours(72));
        mockMvc.perform(post("/api/unseal-orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"req-api-unseal","sealNo":"SEAL-API-1",
                                 "expectedVersion":1,"approver1":"授权人甲","approver2":"授权人乙",
                                 "validFrom":"%s","validTo":"%s","quota":2}
                                """.formatted(from, to)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("ACTIVE"))
                .andExpect(jsonPath("$.quotaTotal").value(2))
                .andExpect(jsonPath("$.quotaUsed").value(0));

        // 4. 受控调节：版本一致，开度 50 → 55，版本 +1，消费一次额度
        mockMvc.perform(post("/api/stations/1/sealed-adjustments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"req-api-sadj","unitId":1,"stepPercent":5,
                                 "expectedVersion":1,"unsealOrderId":1}
                                """))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("EXECUTING"))
                .andExpect(jsonPath("$.newOpening").value(55.00))
                .andExpect(jsonPath("$.unsealOrderId").value(1));

        // 5. 额度轨迹：已消费 1/2，轨迹含本次调节
        mockMvc.perform(get("/api/unseal-orders/1/quota-trace"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.order.quotaUsed").value(1))
                .andExpect(jsonPath("$.adjustments[0].requestId").value("req-api-sadj"));

        // 6. 复封：两名不同人员核对当前版本（已为 2），登记新铅封号
        mockMvc.perform(post("/api/stations/1/units/1/reseal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"req-api-reseal","expectedVersion":2,
                                 "newSealNo":"SEAL-API-2","confirmer1":"核对人甲",
                                 "confirmer2":"核对人乙","sealedAt":"%s"}
                                """.formatted(clock.instant())))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sealNo").value("SEAL-API-2"))
                .andExpect(jsonPath("$.valveVersion").value(2));

        // 7. 旧解封单已终结，历史封号链保留
        mockMvc.perform(get("/api/unseal-orders/1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CLOSED"));
        mockMvc.perform(get("/api/stations/1/units/1/seals"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].sealNo").value("SEAL-API-1"))
                .andExpect(jsonPath("$[0].status").value("RESEALED"))
                .andExpect(jsonPath("$[1].sealNo").value("SEAL-API-2"))
                .andExpect(jsonPath("$[1].status").value("ACTIVE"));
    }

    @Test
    void 错误语义映射() throws Exception {
        // 400：缺少必填参数
        mockMvc.perform(post("/api/stations/1/units/1/seal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"sealNo\":\"SEAL-X\",\"expectedVersion\":1,"
                                + "\"sealedAt\":\"2026-09-26T00:00:00Z\"}"))
                .andExpect(status().isBadRequest());

        // 404：单元不存在
        mockMvc.perform(post("/api/stations/1/units/99/seal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-404\",\"sealNo\":\"SEAL-X\","
                                + "\"expectedVersion\":1,\"sealedAt\":\"2026-09-26T00:00:00Z\"}"))
                .andExpect(status().isNotFound());
        // 404：解封单不存在
        mockMvc.perform(get("/api/unseal-orders/999"))
                .andExpect(status().isNotFound());

        mockMvc.perform(post("/api/stations/1/units/1/seal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-err-seal\",\"sealNo\":\"SEAL-ERR\","
                                + "\"expectedVersion\":1,\"sealedAt\":\"2026-09-26T00:00:00Z\"}"))
                .andExpect(status().isOk());

        // 409：开度版本不一致
        mockMvc.perform(post("/api/unseal-orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-err-ver\",\"sealNo\":\"SEAL-ERR\","
                                + "\"expectedVersion\":9,\"approver1\":\"授权人甲\","
                                + "\"approver2\":\"授权人乙\",\"validFrom\":\"2026-09-26T00:00:00Z\","
                                + "\"validTo\":\"2026-09-27T00:00:00Z\",\"quota\":2}"))
                .andExpect(status().isConflict());
        // 409：同键异参
        mockMvc.perform(post("/api/stations/1/units/1/seal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-err-seal\",\"sealNo\":\"SEAL-ERR-2\","
                                + "\"expectedVersion\":1,\"sealedAt\":\"2026-09-26T00:00:00Z\"}"))
                .andExpect(status().isConflict());

        // 422：两名授权人相同
        mockMvc.perform(post("/api/unseal-orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-err-same\",\"sealNo\":\"SEAL-ERR\","
                                + "\"expectedVersion\":1,\"approver1\":\"授权人甲\","
                                + "\"approver2\":\"授权人甲\",\"validFrom\":\"2026-09-26T00:00:00Z\","
                                + "\"validTo\":\"2026-09-27T00:00:00Z\",\"quota\":2}"))
                .andExpect(status().isUnprocessableEntity());
        // 422：额度超过两次
        mockMvc.perform(post("/api/unseal-orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-err-quota\",\"sealNo\":\"SEAL-ERR\","
                                + "\"expectedVersion\":1,\"approver1\":\"授权人甲\","
                                + "\"approver2\":\"授权人乙\",\"validFrom\":\"2026-09-26T00:00:00Z\","
                                + "\"validTo\":\"2026-09-27T00:00:00Z\",\"quota\":3}"))
                .andExpect(status().isUnprocessableEntity());
    }
}

